#include <unistd.h>
#include <libgpiod.h>

#define GPIO_2 2
#define GPIO_3 3

int main(void)
{
    // Open the GPIO device
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: unable to open GPIO device\n");
        return 1;
    }

    // Set the GPIO direction to output
    if (gpiod_chip_set_direction(chip, GPIO_2, GPIO_OUT) < 0) {
        fprintf(stderr, "Error: unable to set GPIO direction\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO direction to output
    if (gpiod_chip_set_direction(chip, GPIO_3, GPIO_OUT) < 0) {
        fprintf(stderr, "Error: unable to set GPIO direction\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO value to 0
    if (gpiod_chip_set_value(chip, GPIO_2, 0) < 0) {
        fprintf(stderr, "Error: unable to set GPIO value\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO value to 0
    if (gpiod_chip_set_value(chip, GPIO_3, 0) < 0) {
        fprintf(stderr, "Error: unable to set GPIO value\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Loop until interrupted
    while (1) {
        // Toggle the GPIO value
        if (gpiod_chip_set_value(chip, GPIO_2, 1) < 0) {
            fprintf(stderr, "Error: unable to set GPIO value\n");
            gpiod_chip_close(chip);
            return 1;
        }

        // Toggle the GPIO value
        if (gpiod_chip_set_value(chip, GPIO_3, 1) < 0) {
            fprintf(stderr, "Error: unable to set GPIO value\n");
            gpiod_chip_close(chip);
            return 1;
        }

        // Sleep for 2 seconds
        sleep(2);
    }

    // Close the GPIO device
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_2 2
#define GPIO_3 3

static volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line_2, *line_3;
    int ret;

    // Initialize the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request the GPIO lines
    line_2 = gpiod_chip_get_line(chip, GPIO_2);
    line_3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line_2 || !line_3) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO lines to output
    ret = gpiod_line_request_output(line_2, "my-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request output on GPIO %d\n", GPIO_2);
        gpiod_line_free(line_2);
        gpiod_line_free(line_3);
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_output(line_3, "my-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request output on GPIO %d\n", GPIO_3);
        gpiod_line_free(line_2);
        gpiod_line_free(line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO lines to high
    ret = gpiod_line_set_value(line_2, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO %d to high\n", GPIO_2);
        gpiod_line_free(line_2);
        gpiod_line_free(line_3);
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_set_value(line_3, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO %d to high\n", GPIO_3);
        gpiod_line_free(line_2);
        gpiod_line_free(line_3);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up the signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Loop until interrupted
    while (!stop) {
        // Read the GPIO lines
        int value_2 = gpiod_line_get_value(line_2);
        int value_3 = gpiod_line_get_value(line_3);
        if (value_2 < 0 || value_3 < 0) {
            fprintf(stderr, "Failed to read GPIO values\n");
            break;
        }

        // Print the GPIO values
        printf("GPIO %d: %d\n", GPIO_2, value_2);
        printf("GPIO %d: %d\n", GPIO_3, value_3);

        // Sleep for 0.1 seconds
        usleep(100000);
    }

    // Release the GPIO lines
    gpiod_line_free(line_2);
    gpiod_line_free(line_3);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

