    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: unable to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO line as output
    if (gpiod_line_request_output(line, "my-output", 0) < 0) {
        fprintf(stderr, "Error: unable to set GPIO line as output\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the initial state of the GPIO line
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error: unable to set initial state of GPIO line\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Loop until interrupted
    while (1) {
        // Read the current state of the GPIO line
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error: unable to read GPIO line\n");
            gpiod_line_free(line);
            gpiod_chip_close(chip);
            return 1;
        }

        // Print the current state of the GPIO line
        printf("GPIO line state: %d\n", value);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Release the GPIO line and close the chip
    gpiod_line_free(line);
    gpiod_chip_close(chip);

    return 0;
}

