#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define MLX90614_ADDR 0x5a
#define MLX90614_REG_TEMP 0x07

int main(void) {
    int fd;
    int ret;
    uint8_t buf[2];
    uint16_t temp;

    // Open the I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    ret = ioctl(fd, I2C_SLAVE, MLX90614_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Read the temperature register
    ret = read(fd, buf, 2);
    if (ret < 0) {
        perror("Failed to read temperature register");
        close(fd);
        return 1;
    }

    // Convert the temperature to a 16-bit value
    temp = (buf[0] << 8) | buf[1];

    // Print the temperature
    printf("Temperature: %d\n", temp);

    // Close the I2C device
    close(fd);

    return 0;
}

