    config.comp_pol = ADS1115_COMP_POL_LOW;
    config.comp_lat = ADS1115_COMP_LAT_NONLAT;
    config.comp_que = ADS1115_COMP_QUE_1CONV;
    config.drdy = ADS1115_DRDY_EN;
    config.alert_pin = ADS1115_ALERT_PIN_DIS;
    config.alert_pol = ADS1115_ALERT_POL_LOW;
    config.alert_lat = ADS1115_ALERT_LAT_NONLAT;
    config.alert_que = ADS1115_ALERT_QUE_1CONV;
    config.conv_mode = ADS1115_CONV_MODE_SINGLE;
    config.conv_rate = ADS1115_CONV_RATE_128SPS;
    config.os = ADS1115_OS_SINGLE;
    config.mux = ADS1115_MUX_AIN0;
    config.pwr_mode = ADS1115_PWR_MODE_NORMAL;
    config.gain = ADS1115_GAIN_1;
    config.input_range = ADS1115_INPUT_RANGE_4_096V;
    config.data_rate = ADS1115_DATA_RATE_128SPS;
