#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 18

int main(void) {
    int pi;
    int gpio;
    int state = 0;

    // Initialize pigpio
    if ((pi = pigpio_start(NULL, NULL)) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set GPIO 18 as an output
    if ((gpio = pigpio_gpio_export(pi, GPIO_PIN)) < 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_PIN);
        pigpio_stop(pi);
        return 1;
    }

    // Set the initial state to 0
    if (pigpio_gpio_write(pi, gpio, state) < 0) {
        fprintf(stderr, "Failed to set initial state to 0\n");
        pigpio_stop(pi);
        return 1;
    }

    // Set the PWM frequency to 100 Hz
    if (pigpio_gpio_pwm(pi, gpio, 100) < 0) {
        fprintf(stderr, "Failed to set PWM frequency to 100 Hz\n");
        pigpio_stop(pi);
        return 1;
    }

    // Set the PWM range to 100
    if (pigpio_gpio_pwm_range(pi, gpio, 100) < 0) {
        fprintf(stderr, "Failed to set PWM range to 100\n");
        pigpio_stop(pi);
        return 1;
    }

    // Set the PWM duty cycle to 50
    if (pigpio_gpio_pwm_dutycycle(pi, gpio, 50) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle to 50\n");
        pigpio_stop(pi);
        return 1;
    }

    // Start the PWM
    if (pigpio_gpio_pwm_start(pi, gpio) < 0) {
        fprintf(stderr, "Failed to start PWM\n");
        pigpio_stop(pi);
        return 1;
    }

    // Loop until interrupted
    while (1) {
        // Read the current state
        if (pigpio_gpio_read(pi, gpio, &state) < 0) {
            fprintf(stderr, "Failed to read state\n");
            pigpio_stop(pi);
            return 1;
        }

        // Print the state
        printf("State: %d\n", state);

        // Sleep for 0.5 seconds
        usleep(500000);
    }

    // Clean up on exit
    pigpio_gpio_pwm_stop(pi, gpio);
    pigpio_gpio_unexport(pi, gpio);
    pigpio_stop(pi);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 27

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    int trig_value, echo_value;

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        return 1;
    }

    // Request lines for TRIG and ECHO pins
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig_line || !echo_line) {
        fprintf(stderr, "Error: unable to get GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up TRIG and ECHO pins as output and input
    gpiod_line_request_output(trig_line, "trig", 0);
    gpiod_line_request_input(echo_line, "echo");

    // Set up a loop to read the ECHO pin and report the state
    while (running) {
        // Set TRIG pin to high for 10 us
        gpiod_line_set_value(trig_line, 1);
        usleep(10);
        gpiod_line_set_value(trig_line, 0);

        // Read the ECHO pin and report the state
        echo_value = gpiod_line_get_value(echo_line);
        printf("ECHO pin is %s\n", echo_value ? "high" : "low");

        // Sleep for 60 seconds
        sleep(60);
    }

    // Release the GPIO lines and close the chip
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <ads1115.h>

#define I2C_DEV "/dev/i2c-1"
#define ADS1115_ADDR 0x28

int main(void) {
    int fd;
    int ret;
    int16_t reading;
    struct i2c_msg msg;
    struct i2c_rdwr_ioctl_data ioctl_data;

    // Open the I2C device
    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    ioctl(fd, I2C_SLAVE, ADS1115_ADDR);

    // Initialize the ADS1115
    ret = ads1115_init(fd);
    if (ret < 0) {
        perror("Failed to initialize ADS1115");
        return 1;
    }

    // Set the ADS1115 to continuous conversion mode
    ret = ads1115_set_mode(fd, ADS1115_MODE_CONTINUOUS);
    if (ret < 0) {
        perror("Failed to set ADS1115 mode");
        return 1;
    }

    // Set the ADS1115 to sample the analog channel
    ret = ads1115_set_channel(fd, ADS1115_CHANNEL_0);
    if (ret < 0) {
        perror("Failed to set ADS1115 channel");
        return 1;
    }

    // Set the ADS1115 to 12-bit resolution
    ret = ads1115_set_resolution(fd, ADS1115_RESOLUTION_12BIT);
    if (ret < 0) {
        perror("Failed to set ADS1115 resolution");
        return 1;
    }

    // Set the ADS1115 to 860 samples per second
    ret = ads1115_set_rate(fd, ADS1115_RATE_860SPS);
    if (ret < 0) {
        perror("Failed to set ADS1115 rate");
        return 1;
    }

    // Set the ADS1115 to start conversion
    ret = ads1115_start_conversion(fd);
    if (ret < 0) {
        perror("Failed to start ADS1115 conversion");
        return 1;
    }

    // Read the ADS1115 data
    while (1) {
        // Read the ADS1115 data
        ret = ads1115_read_data(fd, &reading);
        if (ret < 0) {
            perror("Failed to read ADS1115 data");
            return 1;
        }

        // Check the validity of the reading
        if (reading < 0 || reading > 0x7FFF) {
            fprintf(stderr, "Invalid ADS1115 reading: %d\n", reading);
            return 1;
        }

        // Print the reading to standard output
        printf("%d\n", reading);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Release the ADS1115
    ret = ads1115_release(fd);
    if (ret < 0) {
        perror("Failed to release ADS1115");
        return 1;
    }

    // Close the I2C device
    close(fd);

    return 0;
}

