#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <ads1115.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x48

int main(void) {
    int fd;
    int i;
    int16_t reading;

    // Open the I2C device
    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Initialize the ADS1115
    if (ads1115_init(fd) < 0) {
        perror("Failed to initialize ADS1115");
        close(fd);
        return 1;
    }

    // Take 3 readings
    for (i = 0; i < 3; i++) {
        // Read the analog channel
        if (ads1115_read_channel(fd, &reading) < 0) {
            perror("Failed to read analog channel");
            close(fd);
            return 1;
        }

        // Print the reading
        printf("Reading: %d\n", reading);

        // Wait for 1 second
        sleep(1);
    }

    // Release the hardware
    ads1115_release(fd);
    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_8 8
#define GPIO_9 9
#define GPIO_10 10
#define GPIO_11 11
#define GPIO_23 23
#define GPIO_24 24

#define NUM_GPIOS 5

int main(int argc, char *argv[]) {
    // Initialize libgpiod
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Set up GPIO lines
    struct gpiod_line *lines[NUM_GPIOS];
    for (int i = 0; i < NUM_GPIOS; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", i);
            return 1;
        }

        if (gpiod_line_request_output(lines[i], "my-program", 0) < 0) {
            fprintf(stderr, "Failed to request output on GPIO line %d\n", i);
            return 1;
        }
    }

    // Set up signal handler to clean up on exit
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    for (int i = 0; i < 256; i++) {
        // Toggle GPIO lines
        for (int j = 0; j < NUM_GPIOS; j++) {
            gpiod_line_set_value(lines[j], !gpiod_line_get_value(lines[j]));
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    for (int i = 0; i < NUM_GPIOS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

void cleanup(int signum) {
    // Release GPIO lines
    for (int i = 0; i < NUM_GPIOS; i++) {
        gpiod_line_release(lines[i]);
    }

    // Close GPIO chip
    gpiod_chip_close(chip);

    // Exit
    exit(0);
}

