#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 2

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value;

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO line to output mode
    if (gpiod_line_request_output(line, "my-output", 0) < 0) {
        fprintf(stderr, "Failed to set GPIO line to output mode\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Loop until interrupted
    while (running) {
        // Read the GPIO line
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line\n");
            break;
        }

        // Print the state
        printf("GPIO line state: %d\n", value);

        // Sleep for 1 second
        sleep(1);
    }

    // Release the GPIO line
    gpiod_line_free(line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

