#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>

#define DEVICE_PATH "/dev/ttyUSB0"

int main(int argc, char *argv[]) {
    int fd;
    struct termios tio;
    char buf[1024];
    ssize_t nread;

    // Open the serial port
    fd = open(DEVICE_PATH, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    // Set the serial port options
    tcgetattr(fd, &tio);
    cfsetspeed(&tio, B115200);
    tio.c_cflag |= (CLOCAL | CREAD);
    tio.c_cflag &= ~(PARENB | CSTOPB | CSIZE);
    tio.c_cflag |= CS8;
    tio.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tio.c_oflag &= ~OPOST;
    tio.c_cc[VMIN] = 1;
    tio.c_cc[VTIME] = 5;
    tcsetattr(fd, TCSANOW, &tio);

    // Read data from the serial port
    while ((nread = read(fd, buf, sizeof(buf))) > 0) {
        printf("Read %ld bytes: %s\n", nread, buf);
    }

    // Check for errors
    if (nread < 0) {
        perror("read");
        exit(1);
    }

    // Close the serial port
    close(fd);

    return 0;
}

