#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>

#define DEVICE_PATH "/dev/ttyUSB0"

int main(void) {
    int fd;
    struct termios tio;
    char buf[1024];
    ssize_t nread;

    // Open the serial port
    fd = open(DEVICE_PATH, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    // Set the serial port options
    tcgetattr(fd, &tio);
    cfsetospeed(&tio, B115200);
    cfsetispeed(&tio, B115200);
    tio.c_cflag |= (CLOCAL | CREAD);
    tio.c_cflag &= ~(PARENB | CSTOPB | CSIZE);
    tio.c_cflag |= CS8;
    tio.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tio.c_oflag &= ~OPOST;
    tio.c_cc[VMIN] = 1;
    tio.c_cc[VTIME] = 5;
    tcsetattr(fd, TCSANOW, &tio);

    // Read data from the serial port
    while (1) {
        nread = read(fd, buf, sizeof(buf));
        if (nread == -1) {
            perror("read");
            break;
        } else if (nread == 0) {
            break;
        }
        printf("%s", buf);
    }

    // Close the serial port
    close(fd);

    return 0;
}

