#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define MPU6050_REG_ACCEL_XOUT_L 0x3C
#define MPU6050_REG_ACCEL_YOUT_H 0x3D
#define MPU6050_REG_ACCEL_YOUT_L 0x3E
#define MPU6050_REG_ACCEL_ZOUT_H 0x3F
#define MPU6050_REG_ACCEL_ZOUT_L 0x40
#define MPU6050_REG_TEMP_OUT_H 0x41
#define MPU6050_REG_TEMP_OUT_L 0x42
#define MPU6050_REG_GYRO_XOUT_H 0x43
#define MPU6050_REG_GYRO_XOUT_L 0x44
#define MPU6050_REG_GYRO_YOUT_H 0x45
#define MPU6050_REG_GYRO_YOUT_L 0x46
#define MPU6050_REG_GYRO_ZOUT_H 0x47
#define MPU6050_REG_GYRO_ZOUT_L 0x48

int main(int argc, char *argv[]) {
    int fd;
    int ret;
    int i;
    int16_t accel_x, accel_y, accel_z;
    int16_t temp;
    int16_t gyro_x, gyro_y, gyro_z;

    // Open the I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    ret = ioctl(fd, I2C_SLAVE, MPU6050_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Read the accelerometer data
    for (i = 0; i < 100; i++) {
        // Read the accelerometer data
        ret = i2c_smbus_read_word_data(fd, MPU6050_REG_ACCEL_XOUT_H);
        if (ret < 0) {
            perror("Failed to read accelerometer data");
            close(fd);
            return 1;
        }
        accel_x = ret;

        ret = i2c_smbus_read_word_data(fd, MPU6050_REG_ACCEL_YOUT_H);
        if (ret < 0) {
            perror("Failed to read accelerometer data");
            close(fd);
            return 1;
        }
        accel_y = ret;

        ret = i2c_smbus_read_word_data(fd, MPU6050_REG_ACCEL_ZOUT_H);
        if (ret < 0) {
            perror("Failed to read accelerometer data");
            close(fd);
            return 1;
        }
        accel_z = ret;

        // Read the temperature data
        ret = i2c_smbus_read_word_data(fd, MPU6050_REG_TEMP_OUT_H);
        if (ret < 0) {
            perror("Failed to read temperature data");
            close(fd);
            return 1;
        }
        temp = ret;

        // Read the gyroscope data
        ret = i2c_smbus_read_word_data(fd, MPU6050_REG_GYRO_XOUT_H);
        if (ret < 0) {
            perror("Failed to read gyroscope data");
            close(fd);
            return 1;
        }
        gyro_x = ret;

        ret = i2c_smbus_read_word_data(fd, MPU6050_REG_GYRO_YOUT_H);
        if (ret < 0) {
            perror("Failed to read gyroscope data");
            close(fd);
            return 1;
        }
        gyro_y = ret;

        ret = i2c_smbus_read_word_data(fd, MPU6050_REG_GYRO_ZOUT_H);
        if (ret < 0) {
            perror("Failed to read gyroscope data");
            close(fd);
            return 1;
        }
        gyro_z = ret;

        // Print the data
        printf("Accelerometer: x=%d, y=%d, z=%d\n", accel_x, accel_y, accel_z);
        printf("Temperature: %d\n", temp);
        printf("Gyroscope: x=%d, y=%d, z=%d\n", gyro_x, gyro_y, gyro_z);
    }

    // Close the I2C device
    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_14 14
#define GPIO_15 15

static volatile sig_atomic_t stop = 0;

static void sigint_handler(int signum) {
    stop = 1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line_14, *line_15;
    int ret;

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        return 1;
    }

    // Request lines 14 and 15
    line_14 = gpiod_chip_get_line(chip, GPIO_14);
    line_15 = gpiod_chip_get_line(chip, GPIO_15);
    if (!line_14 || !line_15) {
        fprintf(stderr, "Error: unable to request GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up lines as outputs
    ret = gpiod_line_request_output(line_14, "my-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: unable to set GPIO line as output\n");
        gpiod_line_free(line_14);
        gpiod_line_free(line_15);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line_15, "my-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: unable to set GPIO line as output\n");
        gpiod_line_free(line_14);
        gpiod_line_free(line_15);
        gpiod_chip_close(chip);
        return 1;
    }

    // Loop until interrupted
    while (!stop) {
        // Read the state of the lines
        int state_14, state_15;
        ret = gpiod_line_get_value(line_14, &state_14);
        if (ret < 0) {
            fprintf(stderr, "Error: unable to read GPIO line\n");
            break;
        }

        ret = gpiod_line_get_value(line_15, &state_15);
        if (ret < 0) {
            fprintf(stderr, "Error: unable to read GPIO line\n");
            break;
        }

        // Print the state
        printf("GPIO 14: %d\n", state_14);
        printf("GPIO 15: %d\n", state_15);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    gpiod_line_free(line_14);
    gpiod_line_free(line_15);
    gpiod_chip_close(chip);

    return 0;
}

