#include <gpiod.h>

#define GPIO_PIN 23

static volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Initialize the GPIO chip and line
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: unable to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO line as output
    ret = gpiod_line_request_output(line, "my-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: unable to request GPIO output\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the initial state of the GPIO line
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: unable to set GPIO output\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up the signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Loop until the program is interrupted
    while (!stop) {
        // Toggle the state of the GPIO line
        ret = gpiod_line_set_value(line, !gpiod_line_get_value(line));
        if (ret < 0) {
            fprintf(stderr, "Error: unable to set GPIO output\n");
            break;
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Release the GPIO line and chip
    gpiod_line_free(line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 22
#define LED_PIN 27

#define TRIG_HIGH 1
#define TRIG_LOW 0
#define ECHO_HIGH 1
#define ECHO_LOW 0

#define TIMEOUT_US 100000
#define INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line, *led_line;
    int trig_value, echo_value, led_value;
    unsigned int echo_duration;

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Request lines
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!trig_line || !echo_line || !led_line) {
        fprintf(stderr, "Error requesting GPIO lines\n");
        return 1;
    }

    // Set up lines
    gpiod_line_request_output(trig_line, "trig", 0);
    gpiod_line_request_input(echo_line, "echo");
    gpiod_line_request_output(led_line, "led", 0);

    // Main loop
    while (running) {
        // Trigger the sensor
        gpiod_line_set_value(trig_line, TRIG_HIGH);
        usleep(10);
        gpiod_line_set_value(trig_line, TRIG_LOW);

        // Wait for echo
        echo_value = gpiod_line_get_value(echo_line);
        while (echo_value == ECHO_LOW) {
            echo_value = gpiod_line_get_value(echo_line);
        }

        // Measure echo duration
        echo_duration = 0;
        while (echo_value == ECHO_HIGH) {
            echo_duration++;
            usleep(1);
            echo_value = gpiod_line_get_value(echo_line);
        }

        // Calculate distance
        float distance = (float)echo_duration / 58.0;

        // Check validity
        if (distance < 2 || distance > 400) {
            fprintf(stderr, "Invalid distance: %f\n", distance);
            continue;
        }

        // Print distance
        printf("Distance: %f cm\n", distance);

        // Set LED
        led_value = (distance < 100) ? 1 : 0;
        gpiod_line_set_value(led_line, led_value);

        // Wait for next iteration
        usleep(INTERVAL_US);
    }

    // Clean up
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return 0;
}

