#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <paho-mqtt-c/MQTTClient.h>
#include <pigpio.h>

#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "sensor/readings"

#define SENSOR_PIN 21

int main(int argc, char *argv[]) {
    // Initialize the MQTT client
    MQTTClient client;
    MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 0, NULL);

    // Connect to the MQTT broker
    MQTTClient_connect(client, NULL);

    // Initialize the GPIO pin for the sensor
    int sensor_fd = pigpio_start(NULL, NULL);
    if (sensor_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO pin for sensor\n");
        return 1;
    }

    // Set the GPIO pin for the sensor as an input
    if (pigpio_gpio_mode_set(sensor_fd, SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin for sensor as input\n");
        return 1;
    }

    // Read the sensor value
    int sensor_value = pigpio_gpio_read(sensor_fd, SENSOR_PIN);
    if (sensor_value < 0) {
        fprintf(stderr, "Failed to read sensor value\n");
        return 1;
    }

    // Publish the sensor value to the MQTT topic
    char message[100];
    sprintf(message, "Sensor value: %d", sensor_value);
    MQTTClient_publish(client, MQTT_TOPIC, message, strlen(message), 0, 0, NULL);

    // Disconnect from the MQTT broker
    MQTTClient_disconnect(client, 0);

    // Release the GPIO pin for the sensor
    pigpio_stop(sensor_fd);

    return 0;
}

