#include <pigpio.h>

#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "sensor/readings"
#define SENSOR_PIN 21

int main(int argc, char *argv[]) {
  // Initialize the MQTT client
  MQTTClient client;
  MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 0, NULL);

  // Connect to the MQTT broker
  MQTTClient_connect(client, NULL);

  // Initialize the GPIO pin for the sensor
  int sensor_pin = SENSOR_PIN;
  if (gpioInitialise() < 0) {
    fprintf(stderr, "Failed to initialize GPIO\n");
    return 1;
  }

  // Set the GPIO pin as an input
  if (gpioSetMode(sensor_pin, PI_INPUT) < 0) {
    fprintf(stderr, "Failed to set GPIO pin mode\n");
    return 1;
  }

  // Read the sensor value
  int sensor_value = gpioRead(sensor_pin);
  if (sensor_value < 0) {
    fprintf(stderr, "Failed to read sensor value\n");
    return 1;
  }

  // Check if the sensor value is valid
  if (sensor_value < 0 || sensor_value > 1023) {
    fprintf(stderr, "Invalid sensor value: %d\n", sensor_value);
    return 1;
  }

  // Publish the sensor value to the MQTT topic
  char payload[10];
  sprintf(payload, "%d", sensor_value);
  MQTTClient_publish(client, MQTT_TOPIC, payload, strlen(payload), 0, 0, NULL);

  // Disconnect from the MQTT broker
  MQTTClient_disconnect(client, 0);

  // Release the GPIO pin
  gpioTerminate();

  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <paho-mqtt-c/MQTTClient.h>
#include <ads1115.h>

#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "ads1115_publisher"
#define MQTT_TOPIC "ads1115/readings"

#define ADS1115_ADDRESS 0x48
#define ADS1115_CHANNEL 0

#define NUM_READINGS 10

void mqtt_connect(MQTTClient *client) {
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    conn_opts.username = NULL;
    conn_opts.password = NULL;

    int rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        printf("Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        exit(1);
    }
}

void mqtt_disconnect(MQTTClient *client) {
    MQTTClient_disconnect(client, 1000);
}

void mqtt_publish(MQTTClient *client, double value) {
    char payload[32];
    sprintf(payload, "%f", value);
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = strlen(payload);
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    int rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        printf("Failed to publish message: %s\n", MQTTClient_strerror(rc));
        exit(1);
    }
}

void ads1115_init(ads1115_t *ads) {
    ads1115_init_default(ads);
    ads1115_set_address(ads, ADS1115_ADDRESS);
    ads1115_set_channel(ads, ADS1115_CHANNEL);
}

void ads1115_read(ads1115_t *ads, double *value) {
    ads1115_read_default(ads, value);
}

void ads1115_close(ads1115_t *ads) {
    ads1115_close_default(ads);
}

void signal_handler(int signum) {
    printf("Received signal %d, exiting...\n", signum);
    exit(1);
}

int main(int argc, char **argv) {
    MQTTClient client;
    MQTTClient_create(&client, MQTT_CLIENT_ID, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 0);

    ads1115_t ads;
    ads1115_init(&ads);

    signal(SIGINT, signal_handler);

    for (int i = 0; i < NUM_READINGS; i++) {
        double value;
        ads1115_read(&ads, &value);
        mqtt_publish(&client, value);
        sleep(1);
    }

    mqtt_disconnect(&client);
    ads1115_close(&ads);

    return 0;
}

