#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <termios.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>

#define BAUDRATE B9600
#define DEVICE "/dev/ttyAMA0"

int main(void)
{
    int fd;
    struct termios tty;
    char buf[1024];
    int n;

    // Open the serial port
    fd = open(DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("open");
        exit(1);
    }

    // Set the baud rate
    cfsetispeed(&tty, BAUDRATE);
    cfsetospeed(&tty, BAUDRATE);
    if (tcsetattr(fd, TCSANOW, &tty) == -1) {
        perror("tcsetattr");
        exit(1);
    }

    // Set the serial port to non-blocking mode
    if (fcntl(fd, F_SETFL, O_NONBLOCK) == -1) {
        perror("fcntl");
        exit(1);
    }

    // Read data from the serial port
    while (1) {
        n = read(fd, buf, sizeof(buf));
        if (n == -1) {
            perror("read");
            exit(1);
        }
        if (n == 0) {
            break;
        }
        printf("%s", buf);
    }

    // Close the serial port
    close(fd);

    return 0;
}

