    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Set up the I2C read message
    msgs[0].addr = BMP280_I2C_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 6;
    msgs[0].buf = buf;

    // Set up the I2C write message
    msgs[1].addr = BMP280_I2C_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = 6;
    msgs[1].buf = buf;

    // Set up the I2C read/write message set
    msgset.msgs = msgs;
    msgset.nmsgs = 2;

    // Read the measurement from the BMP280
    ret = ioctl(fd, I2C_RDWR, &msgset);
    if (ret < 0) {
        perror("Failed to read measurement from BMP280");
        close(fd);
        return 1;
    }

    // Print the measurement to standard output
    printf("Temperature: %d.%d C\n", buf[0], buf[1]);
    printf("Pressure: %d.%d Pa\n", buf[2], buf[3]);

    // Close the I2C device
    close(fd);

    return 0;
}

