int main(int argc, char *argv[]) {
  // Initialize the MQTT client
  MQTTClient client;
  MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 0, NULL);

  // Connect to the MQTT broker
  MQTTClient_connect(client, NULL);

  // Initialize the GPIO pin for the sensor
  int sensor_pin = pigpio_gpio_init(SENSOR_PIN);
  if (sensor_pin < 0) {
    fprintf(stderr, "Error initializing GPIO pin %d\n", SENSOR_PIN);
    return 1;
  }

  // Read the sensor value
  int sensor_value = pigpio_gpio_read(sensor_pin);
  if (sensor_value < 0) {
    fprintf(stderr, "Error reading sensor value\n");
    return 1;
  }

  // Publish the sensor value to the MQTT topic
  char message[100];
  sprintf(message, "{\"sensor_value\": %d}", sensor_value);
  MQTTClient_publish(client, MQTT_TOPIC, message, strlen(message), 0, 0);

  // Disconnect from the MQTT broker
  MQTTClient_disconnect(client, 0);

  // Release the GPIO pin
  pigpio_gpio_close(sensor_pin);

  return 0;
