#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <paho-mqtt-c/MQTTClient.h>
#include <mcp3008.h>

#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "sensor/readings"

#define MCP3008_CHANNEL 0

int main(int argc, char *argv[]) {
    // Initialize the MQTT client
    MQTTClient client;
    MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 0, NULL);

    // Connect to the MQTT broker
    MQTTClient_connect(client, NULL);

    // Initialize the MCP3008
    mcp3008_t mcp3008;
    mcp3008_init(&mcp3008, MCP3008_CHANNEL);

    // Read the sensor value
    int value = mcp3008_read(&mcp3008);

    // Publish the sensor value to the MQTT topic
    char payload[10];
    sprintf(payload, "%d", value);
    MQTTClient_publish(client, MQTT_TOPIC, payload, strlen(payload), 0, 0);

    // Disconnect from the MQTT broker
    MQTTClient_disconnect(client);

    // Release the MCP3008 resources
    mcp3008_release(&mcp3008);

    // Release the MQTT client resources
    MQTTClient_destroy(&client);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define CAMERA_DEVICE "/dev/video0"
#define IMAGE_FILE "image.jpg"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_buffer buf;
    unsigned char *image;
    size_t image_size;

    // Open the camera device
    fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open camera device");
        return 1;
    }

    // Check if the device is a video device
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query camera capabilities");
        close(fd);
        return 1;
    }

    // Set the camera format
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set camera format");
        close(fd);
        return 1;
    }

    // Allocate memory for the image
    image_size = fmt.fmt.pix.width * fmt.fmt.pix.height * 3;
    image = malloc(image_size);
    if (image == NULL) {
        perror("Failed to allocate memory for image");
        close(fd);
        return 1;
    }

    // Read the image from the camera
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Failed to dequeue buffer");
        close(fd);
        return 1;
    }
    memcpy(image, buf.m.userptr, image_size);
    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Failed to queue buffer");
        close(fd);
        return 1;
    }

    // Save the image to a file
    FILE *fp = fopen(IMAGE_FILE, "wb");
    if (fp == NULL) {
        perror("Failed to open image file");
        close(fd);
        return 1;
    }
    fwrite(image, 1, image_size, fp);
    fclose(fp);

    // Release resources
    free(image);
    close(fd);

    return 0;
}

