        gpiod_line_free(line_17);
        gpiod_line_free(line_18);
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_output(line_18, "my-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: unable to set GPIO 18 as output\n");
        gpiod_line_free(line_17);
        gpiod_line_free(line_18);
        gpiod_chip_close(chip);
        return 1;
    }

