static volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    int ret;

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request lines for TRIG and ECHO pins
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig_line || !echo_line) {
        fprintf(stderr, "Failed to get lines for TRIG and ECHO pins\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up TRIG pin as output and ECHO pin as input
    ret = gpiod_line_request_output(trig_line, "trig", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set TRIG pin as output\n");
        gpiod_line_free(trig_line);
        gpiod_line_free(echo_line);
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_input(echo_line, "echo");
    if (ret < 0) {
        fprintf(stderr, "Failed to set ECHO pin as input\n");
        gpiod_line_free(trig_line);
        gpiod_line_free(echo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up TRIG pin to be high for 10 us
    gpiod_line_set_value(trig_line, 1);
    usleep(10);
    gpiod_line_set_value(trig_line, 0);

    // Read the ECHO pin value
    int echo_value = gpiod_line_get_value(echo_line);
    if (echo_value < 0) {
