}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PWM_1 8
#define GPIO_PWM_2 9
#define GPIO_PWM_3 11
#define GPIO_PWM_4 18

int main(void)
{
    int pwm_1, pwm_2, pwm_3, pwm_4;
    int gpio_1, gpio_2, gpio_3, gpio_4;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set GPIO modes
    gpio_1 = gpioSetMode(GPIO_PWM_1, PI_OUTPUT);
    gpio_2 = gpioSetMode(GPIO_PWM_2, PI_OUTPUT);
    gpio_3 = gpioSetMode(GPIO_PWM_3, PI_OUTPUT);
    gpio_4 = gpioSetMode(GPIO_PWM_4, PI_OUTPUT);

    if (gpio_1 < 0 || gpio_2 < 0 || gpio_3 < 0 || gpio_4 < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        return 1;
    }

    // Set PWM frequencies
    pwm_1 = gpioSetPWMfrequency(GPIO_PWM_1, 1000);
    pwm_2 = gpioSetPWMfrequency(GPIO_PWM_2, 1000);
    pwm_3 = gpioSetPWMfrequency(GPIO_PWM_3, 1000);
    pwm_4 = gpioSetPWMfrequency(GPIO_PWM_4, 1000);

    if (pwm_1 < 0 || pwm_2 < 0 || pwm_3 < 0 || pwm_4 < 0) {
        fprintf(stderr, "Failed to set PWM frequencies\n");
        return 1;
    }

    // Set PWM ranges
    gpioSetPWMrange(GPIO_PWM_1, 100);
    gpioSetPWMrange(GPIO_PWM_2, 100);
    gpioSetPWMrange(GPIO_PWM_3, 100);
    gpioSetPWMrange(GPIO_PWM_4, 100);

    // Set PWM levels
    gpioPWM(GPIO_PWM_1, 50);
    gpioPWM(GPIO_PWM_2, 50);
    gpioPWM(GPIO_PWM_3, 50);
    gpioPWM(GPIO_PWM_4, 50);

    // Loop until interrupted
    while (1) {
        // Read PWM levels
        pwm_1 = gpioGetPWMlevel(GPIO_PWM_1);
        pwm_2 = gpioGetPWMlevel(GPIO_PWM_2);
        pwm_3 = gpioGetPWMlevel(GPIO_PWM_3);
        pwm_4 = gpioGetPWMlevel(GPIO_PWM_4);

        // Print PWM levels
        printf("PWM levels: %d, %d, %d, %d\n", pwm_1, pwm_2, pwm_3, pwm_4);

        // Sleep for 1 second
        sleep(1);
    }

    // Release resources on exit
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define CAMERA_DEVICE "/dev/video0"
#define IMAGE_FILE "image.jpg"
#define CAPTURE_INTERVAL 100000 // 0.1 seconds

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_buffer buf;
    unsigned char *image;
    int ret;

    // Open the camera device
    fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening camera device");
        return 1;
    }

    // Check if the device is a video device
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("Error querying device capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video capture device\n");
        close(fd);
        return 1;
    }

    // Set the format of the image
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    // Allocate memory for the image
    image = malloc(fmt.fmt.pix.sizeimage);
    if (image == NULL) {
        perror("Error allocating memory for image");
        close(fd);
        return 1;
    }

    // Set the buffer for the image
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    buf.length = fmt.fmt.pix.sizeimage;
    buf.m.offset = 0;

    ret = ioctl(fd, VIDIOC_QBUF, &buf);
    if (ret < 0) {
        perror("Error setting buffer");
        close(fd);
        return 1;
    }

    // Start the capture
    ret = ioctl(fd, VIDIOC_STREAMON, &buf.type);
    if (ret < 0) {
        perror("Error starting capture");
        close(fd);
        return 1;
    }

    // Capture the image
    ret = read(fd, image, fmt.fmt.pix.sizeimage);
    if (ret < 0) {
        perror("Error reading image");
        close(fd);
        return 1;
    }

    // Save the image to a file
    FILE *fp = fopen(IMAGE_FILE, "wb");
    if (fp == NULL) {
        perror("Error opening image file");
        close(fd);
        return 1;
    }

    fwrite(image, 1, fmt.fmt.pix.sizeimage, fp);
    fclose(fp);

    // Release the resources
    free(image);
    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 18

int main(void) {
    int pi;
    int pwm;
    int state = 0;

    // Initialize pigpio
    if ((pi = pigpio_start(NULL, NULL)) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set GPIO 18 as an output
    if (gpio_mode_set(pi, GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        return 1;
    }

    // Create a PWM object
    if ((pwm = pwm_create(pi, GPIO_PIN, 0, 1000)) < 0) {
        fprintf(stderr, "Failed to create PWM object\n");
        return 1;
    }

    // Set the PWM frequency to 1000 Hz
    if (pwm_set_frequency(pwm, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return 1;
    }

    // Set the PWM range to 1000
    if (pwm_set_range(pwm, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        return 1;
    }

    // Set the PWM state to 0
    if (pwm_set_state(pwm, state) < 0) {
        fprintf(stderr, "Failed to set PWM state\n");
        return 1;
    }

    // Start the PWM
    if (pwm_start(pwm) < 0) {
        fprintf(stderr, "Failed to start PWM\n");
        return 1;
    }

    // Loop until interrupted
    while (1) {
        // Set the PWM state to the opposite of the current state
        state = !state;
        if (pwm_set_state(pwm, state) < 0) {
            fprintf(stderr, "Failed to set PWM state\n");
            return 1;
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up on exit
    pwm_stop(pwm);
    pwm_delete(pwm);
    gpio_mode_set(pi, GPIO_PIN, PI_INPUT);
    pigpio_stop(pi);

    return 0;
}

