#define GPIO_18 18
#define GPIO_23 23
#define GPIO_24 24

int main(void)
{
    int pi;
    int gpio_18, gpio_23, gpio_24;
    int state = 0;

    // Initialize pigpio
    if ((pi = pigpio_start(NULL, NULL)) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set GPIO 18, 23, and 24 as outputs
    if (gpio_mode_set(pi, GPIO_18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 18 as output\n");
        return 1;
    }
    if (gpio_mode_set(pi, GPIO_23, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 23 as output\n");
        return 1;
    }
    if (gpio_mode_set(pi, GPIO_24, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 24 as output\n");
        return 1;
    }

    // Set the initial state of the outputs
    gpio_write(pi, GPIO_18, state);
    gpio_write(pi, GPIO_23, state);
    gpio_write(pi, GPIO_24, state);

    // Loop until interrupted
    while (1) {
        // Toggle the state of the outputs
        state = !state;
        gpio_write(pi, GPIO_18, state);
        gpio_write(pi, GPIO_23, state);
        gpio_write(pi, GPIO_24, state);

        // Sleep for 0.1 seconds
        usleep(100000);
    }

    // Clean up on exit
    gpio_write(pi, GPIO_18, 0);
    gpio_write(pi, GPIO_23, 0);
    gpio_write(pi, GPIO_24, 0);
    gpio_mode_set(pi, GPIO_18, PI_INPUT);
    gpio_mode_set(pi, GPIO_23, PI_INPUT);
    gpio_mode_set(pi, GPIO_24, PI_INPUT);
    pigpio_stop(pi);

