int main(void) {
    // Initialize the GPIO library
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Set up the GPIO pins
    struct gpiod_line *trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    struct gpiod_line *echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig_line || !echo_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO pins to output
    gpiod_line_request_output(trig_line, "trig", 0);
    gpiod_line_request_output(echo_line, "echo", 0);

    // Set the trigger pin to low
    gpiod_line_set_value(trig_line, 0);

    // Wait for the echo pin to go high
    while (gpiod_line_get_value(echo_line) == 0) {
        usleep(1000);
    }

    // Measure the time between the trigger and echo pulses
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 1) {
        usleep(1000);
    }
    clock_gettime(CLOCK_MONOTONIC, &end);
    long long duration = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);

    // Calculate the distance
    double distance = (double)duration / 58.0;

    // Print the distance
    printf("Distance: %.2f cm\n", distance);

    // Release the GPIO pins
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 23

static volatile sig_atomic_t stop = 0;

static void sigint_handler(int signum) {
    stop = 1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Request the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO line to output mode
    ret = gpiod_line_request_output(line, "my-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO line to high
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Loop until interrupted
    while (!stop) {
        // Read the GPIO line
        ret = gpiod_line_get_value(line);
        if (ret < 0) {
            perror("gpiod_line_get_value");
            gpiod_line_free(line);
            gpiod_chip_close(chip);
            return 1;
        }

        // Print the state
        printf("GPIO %d is %s\n", GPIO_PIN, ret ? "high" : "low");

        // Sleep for 5 seconds
        sleep(5);
    }

    // Release the GPIO line
    gpiod_line_free(line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

