#include <libgpiod.h>

#define GPIO_2 2
#define GPIO_3 3
#define GPIO_17 17

int main(void)
{
    // Initialize the GPIO pins
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    struct gpiod_line *line_2 = gpiod_chip_get_line(chip, GPIO_2);
    struct gpiod_line *line_3 = gpiod_chip_get_line(chip, GPIO_3);
    struct gpiod_line *line_17 = gpiod_chip_get_line(chip, GPIO_17);

    if (!line_2 || !line_3 || !line_17) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO pins as outputs
    gpiod_line_request_output(line_2, "my-output", 0);
    gpiod_line_request_output(line_3, "my-output", 0);
    gpiod_line_request_output(line_17, "my-output", 0);

    // Set the initial state of the GPIO pins
    gpiod_line_set_value(line_2, 0);
    gpiod_line_set_value(line_3, 0);
    gpiod_line_set_value(line_17, 0);

    // Loop for 3 cycles, setting the state of the GPIO pins every 5 seconds
    for (int i = 0; i < 3; i++) {
        // Set the state of the GPIO pins
        gpiod_line_set_value(line_2, 1);
        gpiod_line_set_value(line_3, 1);
        gpiod_line_set_value(line_17, 1);

        // Wait for 5 seconds
        sleep(5);

        // Set the state of the GPIO pins
        gpiod_line_set_value(line_2, 0);
        gpiod_line_set_value(line_3, 0);
        gpiod_line_set_value(line_17, 0);

        // Wait for 5 seconds
        sleep(5);
    }

    // Release the GPIO pins
    gpiod_line_release(line_2);
    gpiod_line_release(line_3);
    gpiod_line_release(line_17);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

