#include <gpiod.h>

#define GPIO_17 17
#define GPIO_18 18
#define GPIO_27 27

static void handle_signal(int signum)
{
    printf("Received signal %d, releasing GPIO resources\n", signum);
    gpiod_release(GPIO_17);
    gpiod_release(GPIO_18);
    gpiod_release(GPIO_27);
    exit(0);
}

int main(void)
{
    int gpio_17, gpio_18, gpio_27;

    // Set up signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO 17, 18, and 27 for output
    gpio_17 = gpiod_open(GPIO_17, GPIOD_OUTPUT);
    gpio_18 = gpiod_open(GPIO_18, GPIOD_OUTPUT);
    gpio_27 = gpiod_open(GPIO_27, GPIOD_OUTPUT);

    // Check for errors
    if (gpio_17 < 0 || gpio_18 < 0 || gpio_27 < 0) {
        printf("Error opening GPIO %d, %d, or %d\n", GPIO_17, GPIO_18, GPIO_27);
        return 1;
    }

    // Set GPIO 17, 18, and 27 to high
    gpiod_set(gpio_17, 1);
    gpiod_set(gpio_18, 1);
    gpiod_set(gpio_27, 1);

    // Report the state
    printf("GPIO 17: %d\n", gpiod_get(gpio_17));
    printf("GPIO 18: %d\n", gpiod_get(gpio_18));
    printf("GPIO 27: %d\n", gpiod_get(gpio_27));

    // Release GPIO resources
    gpiod_release(gpio_17);
    gpiod_release(gpio_18);
    gpiod_release(gpio_27);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define SHT31_ADDR 0x44
#define SHT31_MEAS_HIGH 0x2400
#define SHT31_MEAS_LOW 0x240B
#define SHT31_MEAS_HIGH_REP 0x2C06
#define SHT31_MEAS_LOW_REP 0x2C0D
#define SHT31_READ_STATUS 0xF32D
#define SHT31_CLEAR_STATUS 0x3041
#define SHT31_SOFT_RESET 0x30A2
#define SHT31_HEATER_ENABLE 0x306D
#define SHT31_HEATER_DISABLE 0x3066

int main(void) {
    int fd;
    uint16_t data[6];
    uint16_t status;
    uint16_t config;
    uint16_t heater;
    uint16_t temp;
    uint16_t humidity;

    // Open the I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Check if the device is present
    if (ioctl(fd, I2C_SLAVE_FORCE, 0) < 0) {
        perror("Device not present");
        close(fd);
        return 1;
    }

    // Read the status register
    if (read(fd, &status, 2) != 2) {
        perror("Failed to read status register");
        close(fd);
        return 1;
    }

    // Check if the device is in a valid state
    if (status & 0x0003) {
        perror("Device not in valid state");
        close(fd);
        return 1;
    }

    // Read the configuration register
    if (read(fd, &config, 2) != 2) {
        perror("Failed to read configuration register");
        close(fd);
        return 1;
    }

    // Check if the heater is enabled
    if (config & 0x0010) {
        perror("Heater is enabled");
        close(fd);
        return 1;
    }

    // Read the temperature and humidity data
    if (read(fd, data, 6) != 6) {
        perror("Failed to read temperature and humidity data");
        close(fd);
        return 1;
    }

    // Check if the data is valid
    if (data[0] & 0x8000) {
        perror("Data is not valid");
        close(fd);
        return 1;
    }

    // Calculate the temperature and humidity values
    temp = (data[0] * 175) / 65535 - 45;
    humidity = (data[1] * 100) / 65535;

    // Print the temperature and humidity values
    printf("Temperature: %d.%d°C\n", temp / 10, temp % 10);
    printf("Humidity: %d.%d%%\n", humidity / 10, humidity % 10);

    // Close the I2C device
    close(fd);

    return 0;
}

