#define TRIG_LOW 0
#define ECHO_HIGH 1
#define ECHO_LOW 0

#define TIMEOUT_US 100000

void cleanup(void) {
    gpiod_release(TRIG_PIN);
    gpiod_release(ECHO_PIN);
    gpiod_release(LED_PIN);
}

void sigint_handler(int signum) {
