int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line, *led_line;
    int trig_value, echo_value, led_value;
    unsigned int timeout_us;

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Open GPIO lines
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!trig_line || !echo_line || !led_line) {
        fprintf(stderr, "Error opening GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set GPIO lines to output
    gpiod_line_request_output(trig_line, "trig", 0);
    gpiod_line_request_output(echo_line, "echo", 0);
    gpiod_line_request_output(led_line, "led", 0);

    // Set initial values
    trig_value = TRIG_LOW;
    echo_value = ECHO_LOW;
    led_value = 0;

    // Main loop
    while (1) {
        // Set trigger pin high
        gpiod_line_set_value(trig_line, TRIG_HIGH);
        usleep(10);

        // Set trigger pin low
        gpiod_line_set_value(trig_line, TRIG_LOW);

        // Wait for echo pin to go high
        timeout_us = TIMEOUT_US;
        while (gpiod_line_get_value(echo_line) == ECHO_LOW && timeout_us > 0) {
            usleep(10);
            timeout_us -= 10;
        }

        // Check for timeout
        if (timeout_us == 0) {
            fprintf(stderr, "Timeout waiting for echo pin to go high\n");
            break;
        }

        // Wait for echo pin to go low
        timeout_us = TIMEOUT_US;
        while (gpiod_line_get_value(echo_line) == ECHO_HIGH && timeout_us > 0) {
            usleep(10);
            timeout_us -= 10;
        }

        // Check for timeout
        if (timeout_us == 0) {
            fprintf(stderr, "Timeout waiting for echo pin to go low\n");
            break;
        }

        // Calculate distance
        led_value = (int)(((float)timeout_us / 1000000) * 34300) / 2;

        // Set LED pin to calculated value
        gpiod_line_set_value(led_line, led_value);

        // Wait for 0.1 seconds
        usleep(100000);
    }

    // Clean up
    cleanup();

    return 0;
}

