#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_18 18

static volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line_17, *line_18;
    int ret;

    // Initialize the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request the lines
    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    line_18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line_17 || !line_18) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the lines as outputs
    ret = gpiod_line_request_output(line_17, "my-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 17 as output\n");
        gpiod_line_free(line_17);
        gpiod_line_free(line_18);
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_output(line_18, "my-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 18 as output\n");
        gpiod_line_free(line_17);
        gpiod_line_free(line_18);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the initial state
    gpiod_line_set_value(line_17, 0);
    gpiod_line_set_value(line_18, 0);

    // Set up the signal handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!stop) {
        // Toggle the state
        gpiod_line_set_value(line_17, !gpiod_line_get_value(line_17));
        gpiod_line_set_value(line_18, !gpiod_line_get_value(line_18));

        // Sleep for 1 second
        sleep(1);
    }

    // Release the lines
    gpiod_line_free(line_17);
    gpiod_line_free(line_18);

    // Close the chip
    gpiod_chip_close(chip);

    return 0;
}

