    int pwm_17, pwm_18, pwm_22, pwm_23, pwm_24, pwm_25;
    int i;

    // Initialize the GPIO pins
    gpio_17 = pigpio_gpio_init(GPIO_17);
    gpio_18 = pigpio_gpio_init(GPIO_18);
    gpio_22 = pigpio_gpio_init(GPIO_22);
    gpio_23 = pigpio_gpio_init(GPIO_23);
    gpio_24 = pigpio_gpio_init(GPIO_24);
    gpio_25 = pigpio_gpio_init(GPIO_25);

    // Check for errors
    if (gpio_17 < 0 || gpio_18 < 0 || gpio_22 < 0 || gpio_23 < 0 || gpio_24 < 0 || gpio_25 < 0) {
        printf("Error initializing GPIO pins\n");
        return 1;
    }

    // Set the GPIO pins to output mode
    pigpio_gpio_set_mode(gpio_17, PI_OUTPUT);
    pigpio_gpio_set_mode(gpio_18, PI_OUTPUT);
    pigpio_gpio_set_mode(gpio_22, PI_OUTPUT);
    pigpio_gpio_set_mode(gpio_23, PI_OUTPUT);
    pigpio_gpio_set_mode(gpio_24, PI_OUTPUT);
    pigpio_gpio_set_mode(gpio_25, PI_OUTPUT);

    // Set the PWM frequencies
    pwm_17 = pigpio_pwm_init(gpio_17, 1000);
    pwm_18 = pigpio_pwm_init(gpio_18, 1000);
    pwm_22 = pigpio_pwm_init(gpio_22, 1000);
    pwm_23 = pigpio_pwm_init(gpio_23, 1000);
    pwm_24 = pigpio_pwm_init(gpio_24, 1000);
    pwm_25 = pigpio_pwm_init(gpio_25, 1000);

    // Check for errors
    if (pwm_17 < 0 || pwm_18 < 0 || pwm_22 < 0 || pwm_23 < 0 || pwm_24 < 0 || pwm_25 < 0) {
        printf("Error initializing PWM\n");
        return 1;
    }

    // Set the PWM duty cycles
    pigpio_pwm_set_dutycycle(pwm_17, 50);
    pigpio_pwm_set_dutycycle(pwm_18, 50);
    pigpio_pwm_set_dutycycle(pwm_22, 50);
    pigpio_pwm_set_dutycycle(pwm_23, 50);
    pigpio_pwm_set_dutycycle(pwm_24, 50);
    pigpio_pwm_set_dutycycle(pwm_25, 50);

