        pigpio_pwm_set_dutycycle(pwm_24, 50 + i);
        pigpio_pwm_set_dutycycle(pwm_25, 50 + i);

        // Sleep for 0.05 seconds
        usleep(50000);

        // Increment the counter
        i++;
    }

    // Clean up on exit
    pigpio_pwm_stop(pwm_17);
    pigpio_pwm_stop(pwm_18);
    pigpio_pwm_stop(pwm_22);
    pigpio_pwm_stop(pwm_23);
    pigpio_pwm_stop(pwm_24);
