#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_17 17
#define GPIO_23 23
#define GPIO_24 24

static volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line_17, *line_23, *line_24;
    int ret;

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request lines
    line_17 = gpiod_chip_get_line(chip, GPIO_17);
    line_23 = gpiod_chip_get_line(chip, GPIO_23);
    line_24 = gpiod_chip_get_line(chip, GPIO_24);
    if (!line_17 || !line_23 || !line_24) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up lines as outputs
    ret = gpiod_line_request_output(line_17, "my-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 17 as output\n");
        gpiod_line_release(line_17);
        gpiod_line_release(line_23);
        gpiod_line_release(line_24);
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_output(line_23, "my-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 23 as output\n");
        gpiod_line_release(line_17);
        gpiod_line_release(line_23);
        gpiod_line_release(line_24);
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_output(line_24, "my-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO 24 as output\n");
        gpiod_line_release(line_17);
        gpiod_line_release(line_23);
        gpiod_line_release(line_24);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set initial state
    gpiod_line_set_value(line_17, 0);
    gpiod_line_set_value(line_23, 0);
    gpiod_line_set_value(line_24, 0);

    // Main loop
    while (!stop) {
        // Toggle state
        gpiod_line_set_value(line_17, !gpiod_line_get_value(line_17));
        gpiod_line_set_value(line_23, !gpiod_line_get_value(line_23));
        gpiod_line_set_value(line_24, !gpiod_line_get_value(line_24));

        // Print state
        printf("GPIO 17: %d\n", gpiod_line_get_value(line_17));
        printf("GPIO 23: %d\n", gpiod_line_get_value(line_23));
        printf("GPIO 24: %d\n", gpiod_line_get_value(line_24));

        // Sleep for 1 second
        sleep(1);
    }

    // Release lines
    gpiod_line_release(line_17);
    gpiod_line_release(line_23);
    gpiod_line_release(line_24);

    // Close chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
