#include <libgpiod.h>

#define DHT22_PIN 4
#define DHT22_BCM_PIN 17

int main(void)
{
    // Initialize the GPIO pin for the DHT22
    struct gpiod_chip *chip = gpiod_chip_open_by_number(DHT22_BCM_PIN);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO line to output mode
    if (gpiod_line_request_output(line, "dht22", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO line to high
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO line value\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Wait for the DHT22 to respond
    usleep(100000);

    // Read the data from the DHT22
    uint8_t data[5];
    if (gpiod_line_read(line, data, 5) < 0) {
        fprintf(stderr, "Failed to read GPIO line\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Check the validity of the data
    if (data[0] + data[1] + data[2] + data[3] != data[4]) {
        fprintf(stderr, "Invalid data\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Print the data
    printf("Temperature: %d.%d\n", data[2], data[3]);
    printf("Humidity: %d.%d\n", data[0], data[1]);

    // Release the GPIO line
    gpiod_line_free(line);

    // Release the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

