#include <pigpio.h>
#include <unistd.h>

#define GPIO_17 17
#define GPIO_18 18
#define GPIO_27 27

int main(void)
{
    int pi;
    int gpio_17, gpio_18, gpio_27;
    int state = 0;

    // Initialize pigpio
    if ((pi = pigpio_start(NULL, NULL)) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set GPIO 17, 18, and 27 as output
    if (gpio_mode_set(pi, GPIO_17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 17 as output\n");
        return 1;
    }
    if (gpio_mode_set(pi, GPIO_18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 18 as output\n");
        return 1;
    }
    if (gpio_mode_set(pi, GPIO_27, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 27 as output\n");
        return 1;
    }

    // Set initial state
    gpio_write(pi, GPIO_17, state);
    gpio_write(pi, GPIO_18, state);
    gpio_write(pi, GPIO_27, state);

    // Loop until interrupted
    while (1) {
        // Toggle state
        state = !state;

        // Write state to GPIO 17, 18, and 27
        gpio_write(pi, GPIO_17, state);
        gpio_write(pi, GPIO_18, state);
        gpio_write(pi, GPIO_27, state);

        // Sleep for 1 second
        sleep(1);
    }

    // Release hardware on exit
    gpio_write(pi, GPIO_17, 0);
    gpio_write(pi, GPIO_18, 0);
    gpio_write(pi, GPIO_27, 0);
    gpio_mode_set(pi, GPIO_17, PI_INPUT);
    gpio_mode_set(pi, GPIO_18, PI_INPUT);
    gpio_mode_set(pi, GPIO_27, PI_INPUT);
    pigpio_stop(pi);

    return 0;
}

