#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define MAX31855_SPI_BUS 0
#define MAX31855_SPI_DEV 0
#define MAX31855_SPI_MODE SPI_MODE_0
#define MAX31855_SPI_BITS_PER_WORD 8
#define MAX31855_SPI_MAX_SPEED_HZ 1000000

int main(void) {
    int spi_fd;
    uint8_t tx_buf[4];
    uint8_t rx_buf[4];
    int ret;

    // Open the SPI device
    spi_fd = open("/dev/spidev" MAX31855_SPI_BUS "." MAX31855_SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set the SPI mode and speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &MAX31855_SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &MAX31855_SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &MAX31855_SPI_MAX_SPEED_HZ);
    if (ret < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        return 1;
    }

    // Read the measurement from the MAX31855
    tx_buf[0] = 0x00;
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;
    tx_buf[3] = 0x00;

    ret = write(spi_fd, tx_buf, 4);
    if (ret < 0) {
        perror("Failed to write to SPI device");
        close(spi_fd);
        return 1;
    }

    ret = read(spi_fd, rx_buf, 4);
    if (ret < 0) {
        perror("Failed to read from SPI device");
        close(spi_fd);
        return 1;
    }

    // Print the measurement
    printf("Measurement: %d\n", rx_buf[0] << 8 | rx_buf[1]);

    // Close the SPI device
    close(spi_fd);

    return 0;
}

