    stop = 1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line, *led_line, *button_line;
    int trig_value, echo_value, led_value, button_value;

    // Initialize the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        return 1;
    }

    // Initialize the GPIO lines
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);

    // Set the GPIO lines to output
    gpiod_line_request_output(trig_line, "trig", 0);
    gpiod_line_request_output(echo_line, "echo", 0);
    gpiod_line_request_output(led_line, "led", 0);
    gpiod_line_request_input(button_line, "button", 0);

    // Set the GPIO lines to their initial values
    gpiod_line_set_value(trig_line, 0);
    gpiod_line_set_value(echo_line, 0);
    gpiod_line_set_value(led_line, 0);
    gpiod_line_set_value(button_line, 0);

    // Set up the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!stop) {
        // Read the button state
        button_value = gpiod_line_get_value(button_line);

        // If the button is pressed, trigger the ultrasonic sensor
        if (button_value) {
            gpiod_line_set_value(trig_line, 1);
            usleep(10);
            gpiod_line_set_value(trig_line, 0);

            // Read the echo value
            echo_value = gpiod_line_get_value(echo_line);

            // If the echo value is high, turn on the LED
            if (echo_value) {
                gpiod_line_set_value(led_line, 1);
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        }
    }

    // Release the GPIO lines
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

