#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 17

static volatile sig_atomic_t stop = 0;

static void sigint_handler(int signum) {
    stop = 1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Request the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO line to output mode
    ret = gpiod_line_request_output(line, "my-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO line to high
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Loop until interrupted
    while (!stop) {
        // Read the GPIO line
        ret = gpiod_line_get_value(line);
        if (ret < 0) {
            perror("gpiod_line_get_value");
            gpiod_line_free(line);
            gpiod_chip_close(chip);
            return 1;
        }

        // Print the state
        printf("GPIO %d is %s\n", GPIO_PIN, ret ? "high" : "low");

        // Sleep for 1 second
        sleep(1);
    }

    // Release the GPIO line
    gpiod_line_free(line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

