#include <signal.h>
#include <libgpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 18

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line;
    int trig_value, echo_value;
    unsigned int echo_duration;

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request lines for TRIG and ECHO pins
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig_line || !echo_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up TRIG pin as output and ECHO pin as input
    gpiod_line_request_output(trig_line, "trig", 0);
    gpiod_line_request_input(echo_line, "echo");

    // Set up a loop to read the ECHO pin and calculate the distance
    while (running) {
        // Set TRIG pin to high for 10 us
        gpiod_line_set_value(trig_line, 1);
        usleep(10);
        gpiod_line_set_value(trig_line, 0);

        // Read the ECHO pin and calculate the duration
        echo_value = gpiod_line_get_value(echo_line);
        if (echo_value < 0) {
            fprintf(stderr, "Failed to read ECHO pin\n");
            continue;
        }
        echo_duration = gpiod_line_get_value(echo_line);

        // Calculate the distance in cm
        double distance = echo_duration * 17150;

        // Print the distance to standard output
        printf("Distance: %.2f cm\n", distance);

        // Sleep for 0.5 seconds
        sleep(0.5);
    }

    // Release the GPIO lines and close the chip
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return 0;
}

