#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 18

int main(void)
{
    int pi;
    int pwm;
    int state;

    // Initialize pigpio
    if ((pi = pigpio_start(NULL, NULL)) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set GPIO 18 as an output
    if (gpio_mode_set(pi, GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        return 1;
    }

    // Create a PWM object
    if ((pwm = pwm_create(pi, GPIO_PIN, 0, 1000)) < 0) {
        fprintf(stderr, "Failed to create PWM object\n");
        return 1;
    }

    // Set the PWM frequency to 1000 Hz
    if (pwm_set_frequency(pwm, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return 1;
    }

    // Set the PWM range to 0-100
    if (pwm_set_range(pwm, 0, 100) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        return 1;
    }

    // Set the PWM state to 50
    if (pwm_set_state(pwm, 50) < 0) {
        fprintf(stderr, "Failed to set PWM state\n");
        return 1;
    }

    // Start the PWM
    if (pwm_start(pwm) < 0) {
        fprintf(stderr, "Failed to start PWM\n");
        return 1;
    }

    // Loop until interrupted
    while (1) {
        // Get the current PWM state
        if (pwm_get_state(pwm, &state) < 0) {
            fprintf(stderr, "Failed to get PWM state\n");
            return 1;
        }

        // Print the current PWM state
        printf("PWM state: %d\n", state);

        // Sleep for 0.1 seconds
        usleep(100000);
    }

    // Clean up on exit
    pwm_stop(pwm);
    pwm_delete(pwm);
    gpio_mode_set(pi, GPIO_PIN, PI_INPUT);
    pigpio_stop(pi);

    return 0;
}

