void sigint_handler(int signum) {
    stop = 1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line, *led_line;
    int trig_value, echo_value, led_value;

    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        return 1;
    }

    // Initialize GPIO lines
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!trig_line || !echo_line || !led_line) {
        fprintf(stderr, "Error: unable to get GPIO lines\n");
        return 1;
    }

    // Set GPIO lines to output
    gpiod_line_request_output(trig_line, "trig", 0);
    gpiod_line_request_output(echo_line, "echo", 0);
    gpiod_line_request_output(led_line, "led", 0);

    // Set GPIO lines to low
    gpiod_line_set_value(trig_line, 0);
    gpiod_line_set_value(echo_line, 0);
    gpiod_line_set_value(led_line, 0);

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (!stop) {
        // Set trigger line to high for 10 us
        gpiod_line_set_value(trig_line, 1);
        usleep(10);
        gpiod_line_set_value(trig_line, 0);

        // Wait for echo line to go high
        while (gpiod_line_get_value(echo_line) == 0) {
            usleep(10);
        }

        // Measure echo time
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_line) == 1) {
            usleep(10);
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        long echo_time = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        // Calculate distance
        double distance = echo_time * 17150;

        // Set LED line to high if distance is less than 100 cm
        if (distance < 100) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        // Print distance
        printf("Distance: %.2f cm\n", distance);
    }

    // Release GPIO lines
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(led_line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

