#include <pigpio.h>
#include <unistd.h>

#define GPIO_2 2
#define GPIO_3 3
#define GPIO_18 18

int main(void)
{
    int pi;
    int gpio_2, gpio_3, gpio_18;
    int state = 0;

    // Initialize pigpio
    if ((pi = pigpio_start(NULL, NULL)) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set GPIO 2, 3, and 18 as outputs
    if (gpio_mode_set(pi, GPIO_2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 2 as output\n");
        return 1;
    }
    if (gpio_mode_set(pi, GPIO_3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 3 as output\n");
        return 1;
    }
    if (gpio_mode_set(pi, GPIO_18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 18 as output\n");
        return 1;
    }

    // Set initial state to 0
    gpio_write(pi, GPIO_2, 0);
    gpio_write(pi, GPIO_3, 0);
    gpio_write(pi, GPIO_18, 0);

    // Loop until interrupted
    while (1) {
        // Toggle state
        state = !state;

        // Set GPIO 2, 3, and 18 to state
        gpio_write(pi, GPIO_2, state);
        gpio_write(pi, GPIO_3, state);
        gpio_write(pi, GPIO_18, state);

        // Report state
        printf("State: %d\n", state);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up on exit
    gpio_write(pi, GPIO_2, 0);
    gpio_write(pi, GPIO_3, 0);
    gpio_write(pi, GPIO_18, 0);
    gpio_mode_set(pi, GPIO_2, PI_INPUT);
    gpio_mode_set(pi, GPIO_3, PI_INPUT);
    gpio_mode_set(pi, GPIO_18, PI_INPUT);
    pigpio_stop(pi);

    return 0;
}

