#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <termios.h>
#include <fcntl.h>
#include <errno.h>

#define DEVICE_PATH "/dev/ttyUSB0"
#define BAUD_RATE 9600
#define TIMEOUT 1000

int main(void) {
    int fd;
    struct termios tio;
    char buf[1024];
    ssize_t nread;

    // Open the serial port
    fd = open(DEVICE_PATH, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("open");
        exit(1);
    }

    // Set the baud rate and other options
    tcgetattr(fd, &tio);
    cfsetispeed(&tio, BAUD_RATE);
    cfsetospeed(&tio, BAUD_RATE);
    tio.c_cflag |= (CLOCAL | CREAD);
    tio.c_lflag |= (ICANON | ECHO | ECHOE | ECHOK | ECHONL | ISIG | IEXTEN);
    tio.c_oflag |= (OPOST | ONLCR);
    tio.c_cc[VMIN] = 0;
    tio.c_cc[VTIME] = TIMEOUT;
    tcsetattr(fd, TCSANOW, &tio);

    // Read data from the serial port
    while (1) {
        nread = read(fd, buf, sizeof(buf));
        if (nread == -1) {
            perror("read");
            exit(1);
        } else if (nread == 0) {
            break;
        }
        printf("%s", buf);
    }

    // Close the serial port
    close(fd);

    return 0;
}

