#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIG_PIN 18
#define ECHO_PIN 23
#define LED_PIN 24

static volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *trig_line, *echo_line, *led_line;
    int trig_value, echo_value, led_value;

    // Initialize the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Initialize the trigger line
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        return 1;
    }

    // Initialize the echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        return 1;
    }

    // Initialize the LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        return 1;
    }

    // Set the trigger line to output
    gpiod_line_request_output(trig_line, "trigger", 0);
    if (gpiod_line_request_output(trig_line, "trigger", 0) < 0) {
        fprintf(stderr, "Failed to set trigger line to output\n");
        return 1;
    }

    // Set the echo line to input
    gpiod_line_request_input(echo_line, "echo");
    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        fprintf(stderr, "Failed to set echo line to input\n");
        return 1;
    }

    // Set the LED line to output
    gpiod_line_request_output(led_line, "led", 0);
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Failed to set LED line to output\n");
        return 1;
    }

    // Set up the signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Loop until the stop signal is received
    while (!stop) {
        // Set the trigger line to high
        gpiod_line_set_value(trig_line, 1);
        usleep(10);

        // Set the trigger line to low
        gpiod_line_set_value(trig_line, 0);

        // Read the echo line
        echo_value = gpiod_line_get_value(echo_line);

        // Calculate the distance
        if (echo_value == 1) {
            led_value = 1;
        } else {
            led_value = 0;
        }

        // Set the LED line to the calculated value
        gpiod_line_set_value(led_line, led_value);

        // Sleep for 100ms
        usleep(100000);
    }

    // Release the lines
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(led_line);

    // Close the chip
    gpiod_chip_close(chip);

    return 0;
}

