    }

    // Set the GPIO line to output mode
    if (gpiod_line_request_output(line, "my-output", 0) < 0) {
        fprintf(stderr, "Failed to set GPIO line to output mode\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO line to high
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO line to high\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Read the GPIO line
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO line\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Print the GPIO line value
    printf("GPIO line value: %d\n", value);

    // Release the GPIO line
    gpiod_line_free(line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 18

int main(void) {
    int pi;
    int pwm;
    int state = 0;

    // Initialize pigpio
    if ((pi = pigpio_start(NULL, NULL)) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set GPIO 18 as an output
    if (gpio_mode_set(pi, GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        return 1;
    }

    // Create a PWM object
    if ((pwm = pwm_create(pi, GPIO_PIN, 0, 1000)) < 0) {
        fprintf(stderr, "Failed to create PWM object\n");
        return 1;
    }

    // Set the PWM frequency to 1000 Hz
    if (pwm_set_frequency(pwm, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return 1;
    }

    // Set the PWM range to 1000
    if (pwm_set_range(pwm, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        return 1;
    }

    // Set the PWM state to 0
    if (pwm_set_state(pwm, 0) < 0) {
        fprintf(stderr, "Failed to set PWM state\n");
        return 1;
    }

    // Start the PWM
    if (pwm_start(pwm) < 0) {
        fprintf(stderr, "Failed to start PWM\n");
        return 1;
    }

    // Loop until interrupted
    while (1) {
        // Set the PWM state to the current state
        if (pwm_set_state(pwm, state) < 0) {
            fprintf(stderr, "Failed to set PWM state\n");
            return 1;
        }

        // Print the current state
        printf("PWM state: %d\n", state);

        // Increment the state
        state = (state + 1) % 1000;

        // Sleep for 0.2 seconds
        usleep(200000);
    }

    // Clean up on exit
    pwm_stop(pwm);
    pwm_delete(pwm);
    gpio_mode_set(pi, GPIO_PIN, PI_INPUT);
    pigpio_stop(pi);

    return 0;
}

